const rows=$input.all().map(x=>x.json);
return rows.map(c=>{
 let status='CLARIFY';
 // Offline smoke only. Production URL validation must use an egress proxy with DNS, IP and redirect checks.
 const whitelisted=typeof c.url==='string'&&/^https:\/\/cdn\.example\.test\/[a-z0-9/_-]+$/i.test(c.url);
 if(!c.verified||c.store!==c.catalogStore||c.isBot||c.chat!=='PRIVATE'||
    !whitelisted||!Number.isSafeInteger(c.price)||c.price<0)status='BLOCKED';
 else if(c.duplicate)status='DUPLICATE';
 else if(c.sku===c.catalogSku)status=c.fresh?'EXACT_VERIFIED':'REVERIFY';
 return {json:{id:c.id,expected:c.expected,actual:status,pass:status===c.expected,
   media_downloaded:0,model_calls:0,provider_sends:0,orders_written:0,production_ready:false}};
});
